/**
 * Safety guards for `scripts/spike-547.mjs` (issue #547 POC).
 *
 * The spike must never push a schema to, or mutate rows in, a database supplied
 * by the caller. This module enforces the contract:
 *
 * 1. the connection URL is only an ADMIN URL: it may create/drop databases in
 *    the cluster, never receive DDL/DML itself;
 * 2. ambiguous URLs (no explicit database, several hosts, options that redirect
 *    the target) are rejected before anything runs;
 * 3. the working database name is generated by the spike (`sf_spike_547_*`) and
 *    asserted as owned before it is interpolated into SQL;
 * 4. the freshly created database must be empty — `CREATE DATABASE` copies
 *    `template1`, so a modified template could pre-seed tables and make
 *    `db:push --force` destructive;
 * 5. cleanup drops ONLY the owned database, and only when the spike created it.
 *
 * Everything except the DB operations is pure so the guarantees are covered by
 * `tests/spike-547-safety.test.ts` without PostgreSQL.
 */

export const SPIKE_DB_PREFIX = 'sf_spike_547_';
const OWNED_DATABASE = new RegExp(`^${SPIKE_DB_PREFIX}[a-z0-9_]+$`);
const ALLOWED_PARAMS = new Set(['sslmode', 'application_name']);

/** Parse and validate the admin URL. Throws with an actionable message. */
export function parseAdminUrl(raw, { allowQueryParams = true } = {}) {
	if (typeof raw !== 'string' || raw.trim() === '') {
		throw new Error('Missing admin PostgreSQL URL. Pass --database-url or DATABASE_URL.');
	}
	let url;
	try {
		url = new URL(raw);
	} catch {
		throw new Error('Invalid PostgreSQL URL: it cannot be parsed.');
	}
	if (url.protocol !== 'postgres:' && url.protocol !== 'postgresql:') {
		throw new Error(`Refusing ${url.protocol}// URL: only postgres:// or postgresql:// is supported.`);
	}
	if (!url.hostname) throw new Error('Refusing a PostgreSQL URL without a host.');
	if (url.hostname.includes(',')) {
		throw new Error('Refusing a multi-host PostgreSQL URL: the target database must be unambiguous.');
	}
	const database = decodeURIComponent(url.pathname.replace(/^\//, ''));
	if (!database || database.includes('/')) {
		throw new Error('Refusing a PostgreSQL URL without an explicit database name.');
	}
	for (const key of url.searchParams.keys()) {
		if (!allowQueryParams || !ALLOWED_PARAMS.has(key)) {
			throw new Error(`Refusing ambiguous connection URL: unsupported parameter "${key}".`);
		}
	}
	return { url, database };
}

/** Connection URL with the password masked, for logs. */
export function redactUrl(raw) {
	const { url } = parseAdminUrl(raw, { allowQueryParams: false });
	if (url.password) url.password = '***';
	return url.toString();
}

/** Generate a unique, clearly owned database name. */
export function spikeDatabaseName(now = Date.now(), random = Math.random()) {
	const suffix = `${now.toString(36)}_${Math.floor(random * 0xffffffff).toString(36)}`;
	return `${SPIKE_DB_PREFIX}${suffix}`.toLowerCase().replace(/[^a-z0-9_]/g, '_');
}

/** A name may be interpolated into SQL only when the spike generated it. */
export function assertOwnedDatabaseName(name) {
	if (typeof name !== 'string' || !OWNED_DATABASE.test(name)) {
		throw new Error(
			`Refusing to touch "${name}": the spike only manages databases prefixed "${SPIKE_DB_PREFIX}".`
		);
	}
	return name;
}

/** Build the working URL by replacing ONLY the database path. */
export function withDatabase(raw, database) {
	assertOwnedDatabaseName(database);
	const { url } = parseAdminUrl(raw);
	url.pathname = `/${database}`;
	return url.toString();
}

/** The working database must be empty before any schema push. */
export function assertDisposableTables(tables) {
	if (!Array.isArray(tables)) throw new Error('Cannot verify the working database: table list unavailable.');
	if (tables.length > 0) {
		throw new Error(
			`Refusing to push into a non-empty database (${tables.length} table(s): ${tables
				.slice(0, 5)
				.join(', ')}${tables.length > 5 ? ', …' : ''}).`
		);
	}
}

/**
 * @typedef {object} OwnedDatabaseOperations
 * @property {string} adminUrl Caller-supplied admin URL (create/drop only).
 * @property {(name: string) => Promise<void>} createDatabase
 * @property {(name: string) => Promise<string[]>} listTables
 * @property {(name: string) => Promise<void>} dropDatabase
 *
 * @typedef {object} OwnedDatabase
 * @property {string} database Generated, spike-owned database name.
 * @property {string} databaseUrl Connection URL pointing at that database.
 */

/**
 * Create a spike-owned database, verify it is empty, run `fn` against it, then
 * drop exactly that database. The caller-supplied admin URL is never used for
 * DDL/DML: only `createDatabase` and `dropDatabase` receive it.
 *
 * On failure to create (for example the name already exists) nothing is dropped,
 * because the spike does not own that database.
 *
 * @template T
 * @param {OwnedDatabaseOperations} operations
 * @param {(context: OwnedDatabase) => Promise<T>} fn
 * @returns {Promise<T>}
 */
export async function withOwnedDatabase({ adminUrl, createDatabase, listTables, dropDatabase }, fn) {
	const database = spikeDatabaseName();
	assertOwnedDatabaseName(database);
	await createDatabase(database);
	try {
		assertDisposableTables(await listTables(database));
		return await fn({ database, databaseUrl: withDatabase(adminUrl, database) });
	} finally {
		await dropDatabase(database);
	}
}
